class JapanMapWidget extends StatefulWidget {
  final void Function(String prefectureName)? onPrefectureTap;
  final bool blinkEnabled;

  const JapanMapWidget({
    super.key,
    this.onPrefectureTap,
    this.blinkEnabled = true,
  });

  @override
  State<JapanMapWidget> createState() => _JapanMapWidgetState();
}

class _JapanMapWidgetState extends State<JapanMapWidget>
    with SingleTickerProviderStateMixin {
  late AnimationController _blinkController;

  // SVGパスとその重心をキャッシュ
  static final List<Path> _cachedPaths = [];
  static final List<Offset> _pathCentroids = [];
  static bool _pathsCached = false;

  static void _buildPathCache() {
    if (_pathsCached) return;
    for (final d in _svgPaths) {
      _cachedPaths.add(_parseSvgPath(d));
      _pathCentroids.add(_computeCentroid(d));
    }
    _pathsCached = true;
  }

  static Offset _computeCentroid(String d) {
    final tokens = d.split(' ');
    double sumX = 0, sumY = 0;
    int count = 0, i = 0;
    while (i < tokens.length) {
      if ((tokens[i] == 'M' || tokens[i] == 'L') && i + 2 < tokens.length) {
        sumX += double.parse(tokens[i + 1]);
        sumY += double.parse(tokens[i + 2]);
        count++;
        i += 3;
      } else {
        i++;
      }
    }
    return count > 0 ? Offset(sumX / count, sumY / count) : Offset.zero;
  }

  @override
  void initState() {
    super.initState();
    _buildPathCache();
    _blinkController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 500),
    )..repeat(reverse: true);
  }

  @override
  void didUpdateWidget(JapanMapWidget oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.blinkEnabled == oldWidget.blinkEnabled) return;
    if (widget.blinkEnabled) {
      _blinkController.repeat(reverse: true);
    } else {
      _blinkController.stop();
      _blinkController.value = 1.0;
    }
  }

  @override
  void dispose() {
    _blinkController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Consumer<CollectionProvider>(
      builder: (context, provider, _) {
        return AnimatedBuilder(
          animation: _blinkController,
          builder: (context, _) {
            return GestureDetector(
              onTapDown: (details) => _handleTap(
                details.localPosition,
                provider,
                context,
              ),
              child: CustomPaint(
                painter: _JapanMapPainter(
                  prefectures: provider.prefectures,
                  blinkValue: _blinkController.value,
                  svgPaths: _cachedPaths,
                ),
                child: const SizedBox.expand(),
              ),
            );
          },
        );
      },
    );
  }

  void _handleTap(
    Offset pos,
    CollectionProvider provider,
    BuildContext context,
  ) {
    final size = context.size;
    if (size == null) return;

    final svgRect = _calcSvgRect(size);
    if (!svgRect.contains(pos)) return;

    final svgX = (pos.dx - svgRect.left) / svgRect.width * _svgW;
    final svgY = (pos.dy - svgRect.top) / svgRect.height * _svgH;
    final tapSvg = Offset(svgX, svgY);

    // パスマップがまだなければ構築
    _JapanMapPainter.ensurePrefMap(provider.prefectures, _pathCentroids);

    // タップされたSVGパスを判定（大きいパスから先に検索）
    for (int i = _cachedPaths.length - 1; i >= 0; i--) {
      if (_cachedPaths[i].contains(tapSvg)) {
        final prefName = _JapanMapPainter.pathPrefMap[i];
        if (prefName != null) {
          widget.onPrefectureTap?.call(prefName);
          return;
        }
      }
    }
  }
}

// SVGの771:800のアスペクト比を保ちながら画面に収める矩形を計算
Rect _calcSvgRect(Size size) {
  const aspect = _svgW / _svgH;
  double drawW, drawH;
  if (size.width / size.height > aspect) {
    drawH = size.height;
    drawW = size.height * aspect;
  } else {
    drawW = size.width;
    drawH = size.width / aspect;
  }
  return Rect.fromLTWH(
    (size.width - drawW) / 2,
    (size.height - drawH) / 2,
    drawW,
    drawH,
  );
}

// SVGパス文字列 → Flutter Path (SVG座標系のまま)
Path _parseSvgPath(String d) {
  final path = Path();
  final tokens = d.split(' ');
  int i = 0;
  while (i < tokens.length) {
    final cmd = tokens[i];
    if (cmd == 'M' && i + 2 < tokens.length) {
      path.moveTo(double.parse(tokens[i + 1]), double.parse(tokens[i + 2]));
      i += 3;
    } else if (cmd == 'L' && i + 2 < tokens.length) {
      path.lineTo(double.parse(tokens[i + 1]), double.parse(tokens[i + 2]));
      i += 3;
    } else if (cmd == 'Z') {
      path.close();
      i += 1;
    } else {
      i += 1;
    }
  }
  return path;
}

bool _pointInPolygon(Offset point, List<Offset> polygon) {
  bool inside = false;
  int j = polygon.length - 1;
  for (int i = 0; i < polygon.length; i++) {
    final xi = polygon[i].dx, yi = polygon[i].dy;
    final xj = polygon[j].dx, yj = polygon[j].dy;
    if (((yi > point.dy) != (yj > point.dy)) &&
        (point.dx < (xj - xi) * (point.dy - yi) / (yj - yi) + xi)) {
      inside = !inside;
    }
    j = i;
  }
  return inside;
}

class _JapanMapPainter extends CustomPainter {
  final List<Prefecture> prefectures;
  final double blinkValue;
  final List<Path> svgPaths;

  // SVGパスindex → 都道府県名のマッピング（一度だけ構築）
  static final Map<int, String> pathPrefMap = {};
  static bool _mapBuilt = false;

  _JapanMapPainter({
    required this.prefectures,
    required this.blinkValue,
    required this.svgPaths,
  });

  static void ensurePrefMap(
      List<Prefecture> prefectures, List<Offset> centroids) {
    if (_mapBuilt) return;
    _mapBuilt = true;

    // _prefectureArea の静的マッピングを使用
    for (final (idx, gesture, name) in _prefectureArea) {
      if (gesture && name.isNotEmpty) {
        pathPrefMap[idx] = name;
      }
    }
  }

  @override
  void paint(Canvas canvas, Size size) {
    // 背景
    canvas.drawRect(
      Rect.fromLTWH(0, 0, size.width, size.height),
      Paint()..color = Colors.white,
    );

    final svgRect = _calcSvgRect(size);
    ensurePrefMap(prefectures,
        _JapanMapWidgetState._pathCentroids);

    canvas.save();
    canvas.translate(svgRect.left, svgRect.top);
    canvas.scale(svgRect.width / _svgW, svgRect.height / _svgH);

    // 都道府県ごとにSVGパスを塗りつぶす
    final prefMap = {for (final p in prefectures) p.name: p};
    for (int i = 0; i < svgPaths.length; i++) {
      final prefName = pathPrefMap[i];
      if (prefName == null) continue;
      final pref = prefMap[prefName];
      if (pref == null) continue;

      Color fillColor = pref.fillColor;
      if (pref.isComplete) {
        final alpha = (40 + blinkValue * 215).round();
        fillColor = pref.region.baseColor.withAlpha(alpha);
      }
      canvas.drawPath(svgPaths[i], Paint()..color = fillColor);
    }

    // SVGパスで境界線を描画
    final outlinePaint = Paint()
      ..color = Colors.black
      ..strokeWidth = 0.8
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    for (final path in svgPaths) {
      canvas.drawPath(path, outlinePaint);
    }

    canvas.restore();
  }

  @override
  bool shouldRepaint(_JapanMapPainter old) =>
      old.blinkValue != blinkValue || old.prefectures != prefectures;
}

/// 都道府県のシェイプをアイコンとして描画するウィジェット
class PrefectureShapeIcon extends StatelessWidget {
  final String prefectureName;
  final double size;
  final Color color;
  final Color strokeColor;

  const PrefectureShapeIcon({
    super.key,
    required this.prefectureName,
    required this.color,
    required this.strokeColor,
    this.size = 40,
  });

  @override
  Widget build(BuildContext context) {
    _JapanMapWidgetState._buildPathCache();

    final paths = <Path>[];
    for (final (idx, gesture, name) in _prefectureArea) {
      if (gesture && name == prefectureName && idx < _JapanMapWidgetState._cachedPaths.length) {
        paths.add(_JapanMapWidgetState._cachedPaths[idx]);
      }
    }

    if (paths.isEmpty) return SizedBox(width: size, height: size);

    return SizedBox(
      width: size,
      height: size,
      child: CustomPaint(
        painter: _PrefectureShapePainter(paths: paths, color: color, strokeColor: strokeColor),
      ),
    );
  }
}

class _PrefectureShapePainter extends CustomPainter {
  final List<Path> paths;
  final Color color;
  final Color strokeColor;

  const _PrefectureShapePainter({required this.paths, required this.color, required this.strokeColor});

  @override
  void paint(Canvas canvas, Size size) {
    if (paths.isEmpty) return;

    Rect? bounds;
    for (final path in paths) {
      final b = path.getBounds();
      if (b.isEmpty) continue;
      bounds = bounds == null ? b : bounds.expandToInclude(b);
    }
    if (bounds == null || bounds.isEmpty) return;

    const padding = 2.0;
    final scaleX = (size.width - padding * 2) / bounds.width;
    final scaleY = (size.height - padding * 2) / bounds.height;
    final scale = scaleX < scaleY ? scaleX : scaleY;

    final dx = padding + (size.width - padding * 2 - bounds.width * scale) / 2 - bounds.left * scale;
    final dy = padding + (size.height - padding * 2 - bounds.height * scale) / 2 - bounds.top * scale;

    canvas.save();
    canvas.translate(dx, dy);
    canvas.scale(scale);

    final fillPaint = Paint()
      ..color = color
      ..style = PaintingStyle.fill;
    final strokePaint = Paint()
      ..color = strokeColor
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.5 / scale;

    for (final path in paths) {
      canvas.drawPath(path, fillPaint);
      canvas.drawPath(path, strokePaint);
    }

    canvas.restore();
  }

  @override
  bool shouldRepaint(_PrefectureShapePainter old) =>
      old.paths != paths || old.color != color || old.strokeColor != strokeColor;
}
